list_dashboard_banners.code:
const response = await client.dashboardBanners.listDashboardBanners();
for (const banner of response.map.banners) {
    console.log(banner.key, banner.title, banner.active, banner.position);
}

create_dashboard_banner.code:
const response = await client.dashboardBanners.createDashboardBanner({
    key: 'spring_sale',
    title: 'Spring sale',
    description: 'Ends Friday.',
    tags: ['Sales'],
    icon: 'tag',
    learn_more: {action: 'open_link', label: 'Learn more', url: 'https://example.com/spring-sale'},
});
console.log(response.map.key, response.map.title, response.map.position);

patch_dashboard_banner.code:
const response = await client.dashboardBanners.patchDashboardBanner('spring_sale', {
    title: 'Spring sale ends today',
    active: false,
});
console.log(response.map.title, response.map.active);
